def h(value):return escape(str(value))
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+h(c)+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+h(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'

